-- 3) Vytvořené pomocí AI: stejné označení (vodoznak chobotnice s „AI“) jako ostatní AI fotky.
UPDATE "settings" SET "value" = (SELECT jsonb_agg(x ORDER BY x) FROM (SELECT DISTINCT jsonb_array_elements_text("value" || '["/media/0206dc1f-5341-4cb8-9c38-883020bde8ed.webp", "/media/02f9fc02-5d19-470e-8f87-b5e165c21e6c.webp", "/media/117fd947-8c54-47b5-a02b-b2f227284de7.webp", "/media/562ffe25-a350-45c4-a7c9-5aa4adddbc87.webp", "/media/6ee0b70d-80a7-4ef6-9c71-aedd7ea1723b.webp", "/media/b58477e4-f48c-473e-bcc1-adb332065206.webp", "/media/cb251bf3-77ea-490f-8be0-1b06c6da8787.webp", "/media/d673fd7f-dfc8-457e-8ee4-8549984f693e.webp", "/media/e9a9743c-be33-4266-b698-70d6223f79be.webp"]'::jsonb) x) s)
WHERE "key" = 'aiImages' AND jsonb_typeof("value") = 'array' AND NOT "value" @> '["/media/0206dc1f-5341-4cb8-9c38-883020bde8ed.webp", "/media/02f9fc02-5d19-470e-8f87-b5e165c21e6c.webp", "/media/117fd947-8c54-47b5-a02b-b2f227284de7.webp", "/media/562ffe25-a350-45c4-a7c9-5aa4adddbc87.webp", "/media/6ee0b70d-80a7-4ef6-9c71-aedd7ea1723b.webp", "/media/b58477e4-f48c-473e-bcc1-adb332065206.webp", "/media/cb251bf3-77ea-490f-8be0-1b06c6da8787.webp", "/media/d673fd7f-dfc8-457e-8ee4-8549984f693e.webp", "/media/e9a9743c-be33-4266-b698-70d6223f79be.webp"]'::jsonb;
